function toSpanish(text) {
  return spanishReplacements.reduce((translated, [english, spanish]) => {
    if (english.includes(" ")) return translated.replaceAll(english, spanish);
    return translated.replace(new RegExp(`\\b${english}\\b`, "gi"), spanish);
  }, text)
    .replace(/\?$/, "?").replace(/\s+/g, " ").trim();
}

const localized = (text) => ({ en: text, es: toSpanish(text) });
const q = (id, question, options, correctOption, explanation, source) => ({ id, question: localized(question), options: options.map(localized), correctOption, explanation: localized(explanation), source: sources[source] });

